-- Age in minutes of the newest World API ingestion across dlt loads or killmails time
SELECT now() AS "time", EXTRACT(EPOCH FROM (now() - MAX(ts))) / 60.0 AS value FROM (
  SELECT MAX(inserted_at) AS ts FROM world_api_dlt._dlt_loads
  UNION ALL SELECT MAX(time) FROM world_api_dlt.killmails
) t;
